t\\\", \\\"127.0.0.1\\\", \\\"::1\\\"}\\n                or parsed.username or parsed.password):\\n            raise PreviewBlocked(\\\"EXTERNAL_OIDC_CONFIG_INVALID\\\")\\n\\n\\ndef serve_limited(*, signed_receipt: Path, identity_file: Path) -> None:\\n    _require_external_oidc()\\n    if not _port_free(8080) or not _port_free(18181):\\n        raise PreviewBlocked(\\\"HTTP_OR_SECOND_RUNTIME_PORT_OCCUPIED\\\")\\n    child_env = {k: v for k, v in os.environ.items()\\n                 if k not in {\\\"AOS_DATABASE_URL\\\", \\\"PGPASSWORD\\\", \\\"PGPASSFILE\\\"}}\\n    child = subprocess.run([sys.executable, str(Path(__file__).resolve()),\\n\", \".evidence/qyh-human-login-quality-review-20261013/scope-clarification.txt\": \"Bounded scope: management_app/serve_management_readonly are the local management-only path on18080. The original _require_external_oidc is the unchanged formal serve_limited path; it rejects localhost/http and is not claimed passed. Material app-integration.txt shows actual App providers nested inside LocalLoginGate. Original GET /v1/auth/oidc returns original public_config; entry config before app import fixes allow-dev=false and token URL. This review does not claim enterprise HTTPS, runtime Host admission, actual browser login or eight workbenches.\\n\", \".evidence/qyh-human-login-quality-review-20261013/public-policy-function-excerpt.txt\": \"\\n@router.get(\\\"/v1/auth/oidc\\\")\\ndef oidc_public_config() -> dict[str, Any]:\\n    return public_config()\\n\\n\", \".evidence/qyh-human-login-quality-review-20261013/current-original-envelope-material-2.txt\": \"import { getApiBase } from \\\"./apiBase\\\";\\nimport { applyMeToTenant, clearAccessToken, getTenant, setAccessToken, type MeResponse } from \\\"./tenant\\\";\\n\\n/** Original server authentication; credentials and refresh tokens never persist. */\\nexport async function loginPassword(username: string, password: string): Promise<void> {\\n  clearAccessToken();\\n  try {\\n    const response = await fetch(`${getApiBase()}/v1/auth/token`, {\\n      method: \\\"POST\\\", cache: \\\"no-store\\\",\\n      headers: { \\\"Content-Type\\\": \\\"application/json\\\" },\\n      body: JSON.stringify({ grantType: \\\"password\\\", username, password }),\\n    });\\n    if (!response.ok) throw new Error();\\n    const tokens = await response.json();\\n    if (typeof tokens.accessToken !== \\\"string\\\" || !tokens.accessToken.trim()) throw new Error();\\n    const tenant = getTenant();\\n    const meResponse = await fetch(`${getApiBase()}/v1/me`, {\\n      cache: \\\"no-store\\\",\\n      headers: { Authorization: `Bearer ${tokens.accessToken}`, \\\"X-Org-Id\\\": tenant.orgId, \\\"X-Project-Id\\\": tenant.projectId },\\n    });\\n    if (!meResponse.ok) throw new Error();\\n    const me: MeResponse = await meResponse.json();\\n    if (!me.subject || !me.orgId || !me.projectId) throw new Error();\\n    applyMeToTenant(me);\\n    setAccessToken(tokens.accessToken);\\n  } catch {\\n    clearAccessToken();\\n    throw new Error(\\\"登录失败，请核对账号、密码及工作区访问权限后重试。\\\");\\n  }\\n}\\n\", \".evidence/qyh-human-login-quality-review-20261013/current-original-envelope-material-3.txt\": \"import { afterEach, describe, expect, it, vi } from \\\"vitest\\\";\\nimport { loginPassword } from \\\"./passwordLogin\\\";\\nimport { clearAccessToken, getAccessToken, getTenant } from \\\"./tenant\\\";\\nimport { act, createElement } from \\\"react\\\";\\nimport { createRoot } from \\\"react-dom/client\\\";\\nimport { LocalLoginGate } from \\\"../components/auth/LocalLoginGate\\\";\\n\\nafterEach(() => { vi.unstubAllGlobals(); clearAccessToken(); });\\ndescribe(\\\"human password login\\\", () => {\\n  it(\\\"uses original grant and canonical me before publishing memory session\\\", async () => {\\n    const fetch = vi.fn().mockResolvedValueOnce(new Response(JSON.stringify({ accessToken: \\\"signed\\\", refreshToken: \\\"discard\\\" })))\\n      .mockResolvedValueOnce(new Response(JSON.stringify({ subject: \\\"human\\\", orgId: \\\"org-org\\\", projectId: \\\"dev-project\\\", workspaceName: \\\"真实工作区\\\", roles: [\\\"admin\\\"], markings: [], tokenKind: \\\"oidc\\\" })));\\n    vi.stubGlobal(\\\"fetch\\\", fetch);\\n    await loginPassword(\\\"user\\\", \\\"private\\\");\\n    expect(fetch.mock.calls[0][0]).toContain(\\\"/v1/auth/token\\\");\\n    expect(JSON.parse(fetch.mock.calls[0][1].body)).toEqual({ grantType: \\\"password\\\", username: \\\"user\\\", password: \\\"private\\\" });\\n    expect(fetch.mock.calls[1][1].headers.Authorization).toBe(\\\"Bearer signed\\\");\\n    expect(getAccessToken()).toBe(\\\"signed\\\");\\n    expect(getTenant().subject).toBe(\\\"human\\\");\\n    expect(localStorage.getItem(\\\"access_token\\\")).toBeNull();\\n    expect(sessionStorage.getItem(\\\"refresh_token\\\")).toBeNull();\\n  });\\n  it(\\\"does not retry rejected credentials or publish a session\\\", async () => {\\n    const fetch = vi.fn().mockResolvedValue(new Response(\\\"private provider detail\\\", { status: 401 }));\\n    vi.stubGlobal(\\\"fetch\\\", fetch);\\n    await expect(loginPassword(\\\"user\\\", \\\"private\\\")).rejects.toThrow(\\\"登录失败\\\");\\n    expect(fetch).toHaveBeenCalledTimes(1);\\n    expect(getAccessToken()).toBeNull();\\n  });\\n  it(\\\"rejects incomplete token responses before fetching identity\\\", async () => {\\n    const fetch = vi.fn().mockResolvedValue(new Response(\\\"{}\\\")); vi.stubGlobal(\\\"fetch\\\", fetch);\\n    await expect(loginPassword(\\\"user\\\", \\\"private\\\")).rejects.toThrow(\\\"登录失败\\\");\\n    expect(fetch).toHaveBeenCalledTimes(1); expect(getAccessToken()).toBeNull();\\n  });\\n  it(\\\"does not expose an unverified session when canonical me fails\\\", async () => {\\n    const fetch = vi.fn().mockResolvedValueOnce(new Response('{\\\"accessToken\\\":\\\"signed\\\"}'))\\n      .mockResolvedValueOnce(new Response(\\\"{}\\\", { status: 403 })); vi.stubGlobal(\\\"fetch\\\", fetch);\\n    await expect(loginPassword(\\\"user\\\", \\\"private\\\")).rejects.toThrow(\\\"登录失败\\\");\\n    expect(getAccessToken()).toBeNull();\\n  });\\n});\\n\\ndescribe(\\\"server login policy gate\\\", () => {\\n  async function renderPolicy(body: unknown, status = 200) {\\n    vi.stubGlobal(\\\"IS_REACT_ACT_ENVIRONMENT\\\", true);\\n    vi.stubGlobal(\\\"fetch\\\", vi.fn().mockResolvedValue(new Response(JSON.stringify(body), { status })));\\n    const container = document.createElement(\\\"div\\\");\\n    const root = createRoot(container);\\n    await act(async () => { root.render(createElement(LocalLoginGate, { children: \\\"business catalog\\\" })); });\\n    const text = container.textContent;\\n    await act(async () => root.unmount());\\n    return text;\\n  }\\n  it(\\\"preserves the explicitly enabled legacy development UI\\\", async () => {\\n    expect(await renderPolicy({ allowDevToken: true })).toContain(\\\"business catalog\\\");\\n  });\\n  it(\\\"requires human login before mounting business consumers\\\", async () => {\\n    const text = await renderPolicy({ allowDevToken: false, tokenUrlConfigured: true, grantTypes: [\\\"password\\\"] });\\n    expect(text).toContain(\\\"登录名\\\"); expect(text).not.toContain(\\\"business catalog\\\");\\n  });\\n  it(\\\"fails closed for unreadable or unsupported login configuration\\\", async () => {\\n    for (const [body, status] of [[{}, 200], [{ allowDevToken: false }, 200], [{}, 503]] as const) {\\n      const text = await renderPolicy(body, status);\\n      expect(text).toContain(\\\"登录服务暂不可用\\\"); expect(text).not.toContain(\\\"business catalog\\\");\\n    }\\n  });\\n});\\n\", \".evidence/qyh-human-login-quality-review-20261013/original-server-response-excerpt.txt\": \"        log.warning(\\\"oidc_password_grant_fail err=%s\\\", type(exc).__name__)\\n        raise ValueError(f\\\"IdP token failed: {exc}\\\") from exc\\n    access = raw.get(\\\"access_token\\\")\\n    if not access:\\n        raise ValueError(\\\"IdP response missing access_token\\\")\\n    return {\\n        \\\"accessToken\\\": access,\\n        \\\"tokenType\\\": raw.get(\\\"token_type\\\") or \\\"Bearer\\\",\\n        \\\"expiresIn\\\": int(raw.get(\\\"expires_in\\\") or 3600),\\n        \\\"issuer\\\": issuer(),\\n        \\\"tokenKind\\\": \\\"oidc-keycloak\\\",\\n        \\\"alg\\\": \\\"RS256\\\",\\n        \\\"refreshToken\\\": raw.get(\\\"refresh_token\\\"),\\n    }\\n\\n\\ndef issue_dev_token(\\n    *,\\n\", \".evidence/qyh-human-login-quality-review-20261013/actual-envelope-correction.txt\": \"Live original API POST returned200; first acceptance script and Web mocked IdP snake_case instead of original AOS camelCase. Corrected current source uses original accessToken exactly; real contract fixture RED1/6PASS then13/13GREEN and corrected production build passed. Preserved initial verifier failure, read-only reconciled its exact single session and closed only known selftest. Second original API credential request and me returned200 with canonical UUID/scope/admin; profile displayName did not match because managed boot loads membership catalog but not legacy person cache. Native logout204 closed that second session. Browser login/legacy profile hydration and eight runtime pages remain pending. No full acceptance claimed.\\n\"}}"}],"timestamp":1791829540824}}
{"type":"message_end","message":{"role":"user","content":[{"type":"text","text":"{\"schema\": \"aos-material-review/v1\", \"request_id\": \"qyh-human-login-quality-review-20261013-r5\", \"task_id\": \"qyh-human-login-quality-review-20261013\", \"owner\": \"codex-01a107a2-e9e4-7670-bc44-1144fa9b27e2\", \"kind\": \"quality\", \"baseline\": {\"head\": \"d589cad90833c0f0165f3be6b4fd8f7a809a7dfb\", \"authority_revision\": \"AOS-001987\", \"files\": {\".evidence/qyh-human-login-quality-review-20261013/public-code-material-0.txt\": \"79977f32ef3645767ad4d674ac8acbf052a28e28a23926da351a8878f4ed312e\", \".evidence/qyh-human-login-quality-review-20261013/public-code-material-1.txt\": \"ba142f98fb73f0d2ce14a352d46e411bef77b49355d396d1a2702114f7d3b63e\", \".evidence/qyh-human-login-quality-review-20261013/public-code-material-4.txt\": \"7a94283b6a392fae46633e584e70727653242578700517102c6c885a0f209816\", \".evidence/qyh-human-login-quality-review-20261013/public-code-material-5.txt\": \"bc21327c1f70f69a27df8be7740b1e1e25897b6b4292e0d5d5a26f50bdfa1cbc\", \".evidence/qyh-human-login-quality-review-20261013/public-code-material-6.txt\": \"8689fa7ba37e804826d10bfb96c8a8b91360f92f1c3a5d668305c799cebea122\", \".evidence/qyh-human-login-quality-review-20261013/public-code-material-7.txt\": \"04fd6519f9f2a97524501ae89a8b08c58e8dcca5c398148de8d82d31a40430eb\", \".evidence/qyh-human-login-quality-review-20261013/app-integration.txt\": \"623e4b79ca8a647e19d3303ccd6e5e00c656fbe0fa2a388f2f84936e491c2f14\", \".evidence/qyh-human-login-quality-review-20261013/formal-entry-boundary-excerpt.txt\": \"83bc055dc259b6f3c028f6936c742b7fb08dd6134280d2d6d052789fbc5410ec\", \".evidence/qyh-human-login-quality-review-20261013/scope-clarification.txt\": \"9c22479a15022e0eeafe67a9eef5342a2ee3637dd2b94f7a5495571d80ac5226\", \".evidence/qyh-human-login-quality-review-20261013/public-policy-function-excerpt.txt\": \"3ed5c20f9e49ff48e3fd1af1e606dc87509d5cd77a7af33053bc2fc4a67b7bb9\", \".evidence/qyh-human-login-quality-review-20261013/current-original-envelope-material-2.txt\": \"e7a90b508f52ba1d00f7607e217a53be720a8a121951a05688e210f8f3e0c397\", \".evidence/qyh-human-login-quality-review-20261013/current-original-envelope-material-3.txt\": \"d61a88a28a51fb4b4d15ca9d6a2bfd07047dd346693e0f628fab2b35dc3a366b\", \".evidence/qyh-human-login-quality-review-20261013/original-server-response-excerpt.txt\": \"87447eaa5c9dcff12bf0f077695e604bec01efe75b4ae59a0035fe018a859e68\", \".evidence/qyh-human-login-quality-review-20261013/actual-envelope-correction.txt\": \"605df63073bfb4292c1e6e6e90e84516970df3d363a19fce174e648de3d9b32c\"}}, \"claims\": [\"Validated exact private local identity configuration opts into original authentication POST only while default readonly business boundaries remain closed.\", \"Web password credentials and refresh tokens are not persisted or queued; access token is published only after original canonical me succeeds.\", \"Server login policy prevents unauthenticated external-only users mounting business catalog consumers and preserves explicitly enabled legacy development UI.\", \"Reported tests and enrollment are bounded code and metadata evidence; live login and eight workbench acceptance remain unproven.\"], \"materials\": {\".evidence/qyh-human-login-quality-review-20261013/public-code-material-0.txt\": \"#!/usr/bin/env python3\\n\\\"\\\"\\\"Read-only HTTP attachment preflight for the preserved Qiyuehui cluster.\\n\\nDefault operation inspects an exact current installation through the original\\nrelease reader. Explicit limited serving additionally requires formal OIDC and\\nan independently verified frozen API source; Host and all workers remain off.\\n\\\"\\\"\\\"\\nfrom __future__ import annotations\\nimport argparse\\nimport hashlib\\nimport json\\nimport os\\nimport stat\\nimport subprocess\\nimport sys\\nfrom contextlib import contextmanager\\nfrom pathlib import Path\\nfrom uuid import UUID\\nimport a0v_current_preview_http as previous\\n\\nROOT = Path(__file__).resolve().parents[1]\\nTARGET = 'qyh-restored-pg-20261011'\\nCONTEXT = 'colima-aos-extension'\\nVOLUME = 'aos-qyh-history159-prepared-data-20261011'\\nIMAGE = 'sha256:7e7dbab8d3b431a20793a6d99cb5a6bc84e44914309917f1bf5589a7568cdefd'\\nEXPECTED = {'database': 'aos_meta_head', 'cluster': '7695302940039200809',\\n    'schema': 'a0v_159', 'orgId': 'org-org', 'orgName': '栖月汇商贸有限公司',\\n    'projectId': 'dev-project', 'tables': 647}\\n# Physical contracts for independently rehearsed migrations of this preserved\\n# cluster. Unknown revisions must be reviewed before the attachment gate opens.\\nSCHEMA_TABLE_COUNTS = {'a0v_159': 647, 'a0v_160': 650, 'a0v_161': 650}\\nSELECTED_VERSIONS = {'domain.ecommerce.core': '1.4.3',\\n    'platform.ecommerce.niushop': '1.23.2', 'solution.ecommerce.growth': '1.13.0',\\n    'solution.ecommerce.operations-base': '1.2.2'}\\nLIMITED_PORT = 18080\\n\\nclass RestorationBlocked(RuntimeError):\\n    pass\\n\\n\\ndef load_management_oidc_config(path):\\n    \\\"\\\"\\\"Private exact local identity routing; never accept credentials here.\\\"\\\"\\\"\\n    def unique(pairs):\\n        value = {}\\n        for key, item in pairs:\\n            if key in value:\\n                raise ValueError('duplicate key')\\n            value[key] = item\\n        return value\\n    try:\\n        path = Path(path)\\n        parent = path.parent.lstat()\\n        if (not path.is_absolute() or not stat.S_ISDIR(parent.st_mode)\\n                or parent.st_uid != os.geteuid() or stat.S_IMODE(parent.st_mode) != 0o700):\\n            raise ValueError('private parent required')\\n        fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)\\n        with os.fdopen(fd, 'rb') as source:\\n            before = os.fstat(source.fileno())\\n            if (not stat.S_ISREG(before.st_mode) or before.st_uid != os.geteuid()\\n                    or stat.S_IMODE(before.st_mode) != 0o600 or not 0 < before.st_size <= 16384):\\n                raise ValueError('private ordinary configuration required')\\n            raw = source.read(16385)\\n            after = os.fstat(source.fileno())\\n        if len(raw) > 16384 or (before.st_size, before.st_mtime_ns) != (after.st_size, after.st_mtime_ns):\\n            raise ValueError('configuration changed')\\n        value = json.loads(raw, object_pairs_hook=unique)\\n        fields = {'schemaVersion','issuer','audience','clientId','jwksUrl','tokenUrl','clockSkewSeconds'}\\n        issuer = 'http://127.0.0.1:18448/realms/qyh-local'\\n        if (type(value) is not dict or set(value) != fields\\n                or value['schemaVersion'] != 'aos.local-management-oidc/v1'\\n                or value['issuer'] != issuer or value['audience'] != 'aos-api'\\n                or value['clientId'] != 'aos-api'\\n                or value['jwksUrl'] != issuer + '/protocol/openid-connect/certs'\\n                or value['tokenUrl'] != issuer + '/protocol/openid-connect/token'\\n                or type(value['clockSkewSeconds']) is not int\\n                or not 0 <= value['clockSkewSeconds'] <= 5):\\n            raise ValueError('exact local identity contract required')\\n        return {'AOS_AUTH_ALLOW_DEV':'0', 'AOS_AUTH_EXTERNAL_ONLY':'1',\\n            'AOS_OIDC_ISSUER':issuer, 'AOS_OIDC_AUDIENCE':'aos-api',\\n            'AOS_OIDC_CLIENT_ID':'aos-api', 'AOS_OIDC_JWKS_URL':value['jwksUrl'],\\n            'AOS_OIDC_ISSUERS':'', 'AOS_OIDC_JWKS_URLS':'',\\n            'AOS_OIDC_TOKEN_URL':value['tokenUrl'], 'AOS_OIDC_TOKEN_ALG':'RS256',\\n            'AOS_OIDC_LEEWAY_SECONDS':str(value['clockSkewSeconds'])}\\n    except (OSError, ValueError, TypeError, KeyError):\\n        raise RestorationBlocked('RESTORED_LOCAL_OIDC_PRIVATE_EXACT_CONFIG_REQUIRED') from None\\n\\n\\nclass ReadOnlyManagementApp:\\n    \\\"\\\"\\\"Local inspection only; product authentication and tenant checks still run.\\\"\\\"\\\"\\n    def __init__(self, app, *, allow_password_login=False):\\n        self.app = app\\n        self.allow_password_login = allow_password_login is True\\n\\n    async def __call__(self, scope, receive, send):\\n        if scope['type'] == 'websocket':\\n            await send({'type': 'websocket.close', 'code': 1008})\\n            return\\n        login = (self.allow_password_login and scope['type'] == 'http'\\n                 and scope['method'] == 'POST' and scope['path'] == '/v1/auth/token')\\n        if scope['type'] == 'http' and scope['method'] not in {'GET', 'HEAD', 'OPTIONS'} and not login:\\n            body = b'{\\\"code\\\":\\\"RESTORED_MANAGEMENT_READ_ONLY\\\",\\\"message\\\":\\\"Management inspection is read only.\\\"}'\\n            await send({'type': 'http.response.start', 'status': 405,\\n                        'headers': [(b'content-type', b'application/json'), (b'cache-control', b'no-store')]})\\n            await send({'type': 'http.response.body', 'body': body})\\n            return\\n        await self.app(scope, receive, send)\\n\\ndef require_identity(observed, *, code_head):\\n    if any(observed.get(k) != v for k,v in EXPECTED.items()\\n           if k not in {'schema', 'tables'}):\\n        raise RestorationBlocked('RESTORED_IDENTITY_DRIFT')\\n    tables = SCHEMA_TABLE_COUNTS.get(observed.get('schema'))\\n    if tables is None or observed.get('tables') != tables:\\n        raise RestorationBlocked('RESTORED_IDENTITY_DRIFT')\\n    if observed['schema'] != code_head:\\n        raise RestorationBlocked('RESTORED_CODE_SCHEMA_DRIFT')\\n\\ndef inventory_report(identity, inventory):\\n    return {'outcome': 'RESTORED_HTTP_ATTACHMENT_INVENTORY_ONLY',\\n        'identity': identity, 'inventory': inventory, 'apiStartAuthorized': False,\\n        'eightWorkbenchesVerified': False, 'runtimeHostEnabled': False,\\n        'remainingGates': ['current signed release and installation',\\n                          'current configuration and formal identity',\\n                          'API/Web restart and eight-page browser acceptance']}\\n\\ndef _private(path):\\n    if path.is_symlink() or not path.is_file():\\n        raise RestorationBlocked('RESTORED_IDENTITY_FILE_INVALID')\\n    s = path.stat()\\n    if stat.S_IMODE(s.st_mode) != 0o600 or s.st_uid != os.getuid():\\n        raise RestorationBlocked('RESTORED_IDENTITY_FILE_PERMISSION')\\n    return path.resolve(strict=True)\\n\\ndef _identity_parameters(identity_file):\\n    data = json.loads(_private(identity_file).read_text())\\n    if (set(data) != {'host','port','dbname','user','pgpassfile'}\\n        or data['host'] != '127.0.0.1' or type(data['port']) is not int\\n        or data['port'] != 18446 or data['dbname'] != EXPECTED['database']\\n        or data['user'] != 'qyh_restored_api_login'):\\n        raise RestorationBlocked('RESTORED_LOGIN_TARGET_DRIFT')\\n    data['pgpassFile'] = str(_private(Path(data.pop('pgpassfile'))))\\n    return data\\n\\ndef preflight(identity_file):\\n    data = _identity_parameters(identity_file)\\n    previous._verify_limited_login(data)\\n    proc = subprocess.run(['docker','--context',CONTEXT,'inspect','--format',\\n        '{\\\"Image\\\":{{json .Image}},\\\"Mounts\\\":{{json .Mounts}},\\\"Ports\\\":{{json .NetworkSettings.Ports}},\\\"State\\\":{{json .State}}}',TARGET],\\n        check=True,capture_output=True,timeout=30)\\n    container = json.loads(proc.stdout)\\n    if (container['Image'] != IMAGE or not container['State']['Running']\\n        or len(container['Mounts']) != 1 or container['Mounts'][0].get('Name') != VOLUME\\n        or container['Ports'].get('5432/tcp') != [{'HostIp':'127.0.0.1','HostPort':'18446'}]):\\n        raise RestorationBlocked('RESTORED_CONTAINER_DRIFT')\\n    # Native cluster control metadata needs local maintenance access. This\\n    # subprocess has a literal READ ONLY query, never service credentials.\\n    sql = \\\"\\\"\\\"BEGIN READ ONLY; SELECT json_build_object(\\n      'database',current_database(),\\n      'cluster',(SELECT system_identifier::text FROM pg_control_system()),\\n      'schema',(SELECT version_num FROM alembic_version),\\n      'orgId',(SELECT id FROM meta_org WHERE id='org-org'),\\n      'orgName',(SELECT name FROM meta_org WHERE id='org-org'),\\n      'projectId',(SELECT project_id FROM meta_workspace WHERE project_id='dev-project' AND org_id='org-org'),\\n      'tables',(SELECT count(*) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.relkind='r' AND n.nspname NOT IN ('pg_catalog','information_schema') AND n.nspname NOT LIKE 'pg_toast%'),\\n      'inventory',json_build_object(\\n        'installations',(SELECT count(*) FROM bundle_installation WHERE org_id='org-org' AND project_id='dev-project'),\\n        'configurations',(SELECT count(*) FROM extension_runtime_configuration WHERE org_id='org-org' AND project_id='dev-project'),\\n        'bindings',(SELECT count(*) FROM extension_runtime_binding WHERE org_id='org-org' AND project_id='dev-project'),\\n        'enabledBindings',(SELECT count(*) FROM extension_runtime_binding WHERE org_id='org-org' AND project_id='dev-project' AND enabled)));\\n      COMMIT;\\\"\\\"\\\"\\n    proc = subprocess.run(['docker','--context',CONTEXT,'exec','-i',TARGET,\\n        'psql','-X','-qAt','-v','ON_ERROR_STOP=1','-U','aos_app','-d','aos_meta_head'],\\n        input=sql.encode(),check=True,capture_output=True,timeout=30)\\n    observed = json.loads(proc.stdout)\\n    inventory = observed.pop('inventory')\\n    require_identity(observed,code_head=previous._code_schema_head())\\n    report = inventory_report(observed, inventory)\\n    report['limitedLoginVerified'] = True\\n    report['volume'] = VOLUME\\n    report['databaseStartedAt'] = container['State']['StartedAt']\\n    return report\\n\\ndef require_selected_installation(view, *, installation_id):\\n    try:\\n        exact_id = str(UUID(installation_id))\\n    except (ValueError, TypeError, AttributeError):\\n        raise RestorationBlocked('RESTORED_INSTALLATION_ID_INVALID') from None\\n    if (view.scope != ('org-org', 'dev-project') or view.installation_id != exact_id\\n        or view.authorization != 'EVIDENCE_ONLY_NO_START'):\\n        raise RestorationBlocked('RESTORED_INSTALLATION_SCOPE_OR_AUTHORITY_DRIFT')\\n    versions = {(r.publisher, r.bundle_id): r.version for r in view.releases}\\n    if (len(view.releases) != 4 or len(versions) != 4\\n        or versions != {('aos', bid): version for bid, version in SELECTED_VERSIONS.items()}):\\n        raise RestorationBlocked('RESTORED_SELECTED_RELEASE_SET_DRIFT')\\n    return {'installationId': exact_id, 'installationRevision': view.current_revision,\\n        'etagVersion': view.etag_version, 'growthVersion': SELECTED_VERSIONS['solution.ecommerce.growth'],\\n        'releases': [{'publisher': r.publisher, 'id': r.bundle_id, 'version': r.version,\\n                      'contentHash': r.content_hash} for r in view.releases],\\n        'authorization': 'CURRENT_INSTALLATION_EVIDENCE_ONLY_NO_START',\\n        'apiStartAuthorized': False, 'runtimeHostEnabled': False,\\n        'currentConfigurationVerified': False, 'eightWorkbenchesVerified': False}\\n\\ndef select_current_installation(*, identity_file, bundle_root, trust_roots_file, installation_id):\\n    report = preflight(identity_file)\\n    parameters = _identity_parameters(identity_file)\\n    sys.path.insert(0, str(ROOT / 'services/aos-api'))\\n    from psycopg import connect\\n    from psycopg.rows import dict_row\\n    from aos_api.asset_registry.manifest_loader import ManifestLoader\\n    from aos_api.asset_registry.release_policy import ReleasePolicy\\n    from aos_api.asset_registry.signature import FileTrustRootProvider\\n    from aos_api.extension_runtime.current_installation_release_evidence import (\\n        CurrentReleaseEvidenceBlocked, read_current_installation_release_evidence,\\n    )\\n    from aos_api.tenant_scope import TenantScope\\n    trust = FileTrustRootProvider(trust_roots_file).snapshot()\\n    loader = ManifestLoader({'a0v-canonical': bundle_root, 'a0v-qyh-current': bundle_root,\\n                             'a0v-current': bundle_root}, trust_roots=trust)\\n\\n    @contextmanager\\n    def factory():\\n        with connect(host=parameters['host'], port=parameters['port'],\\n                     dbname=parameters['dbname'], user=parameters['user'],\\n                     passfile=parameters['pgpassFile'], row_factory=dict_row) as conn:\\n            conn.read_only = True\\n            yield conn\\n    try:\\n        view = read_current_installation_release_evidence(connect_factory=factory,\\n            scope=TenantScope('org-org', 'dev-project'), installation_id=installation_id,\\n            release_policy=ReleasePolicy(trust_roots=trust), loader=loader)\\n    except CurrentReleaseEvidenceBlocked as exc:\\n        raise RestorationBlocked('RESTORED_CURRENT_RELEASE_REJECTED:' + str(exc)) from None\\n    selected = require_selected_installation(view, installation_id=installation_id)\\n    return {**report, 'outcome': 'RESTORED_CURRENT_INSTALLATION_EVIDENCE_ONLY',\\n            'currentInstallation': selected}\\n\\ndef require_api_source_candidate(report_path):\\n    task = ROOT / '.evidence/qyh-full-system-restoration-20261011'\\n    if (report_path.is_symlink() or not report_path.is_file()\\n        or report_path.resolve().parent != task.resolve()\\n        or report_path.stat().st_uid != os.getuid()):\\n        raise RestorationBlocked('RESTORED_API_SOURCE_CANDIDATE_INVALID')\\n    report = json.loads(report_path.read_text())\\n    head = report.get('head', '')\\n    if (type(head) is not str or len(head) != 40\\n        or any(c not in '0123456789abcdef' for c in head)\\n        or report.get('outcome') != 'CURRENT_M1_API_SOURCE_CANDIDATE_FROZEN_NO_START'):\\n        raise RestorationBlocked('RESTORED_API_SOURCE_CANDIDATE_INVALID')\\n    source = task / 'private' / ('api-source-' + head)\\n    if report.get('source') != str(source) or source.resolve() != source or not source.