\\", \\\"127.0.0.1\\\", \\\"::1\\\"}\\n                or parsed.username or parsed.password):\\n            raise PreviewBlocked(\\\"EXTERNAL_OIDC_CONFIG_INVALID\\\")\\n\\n\\ndef serve_limited(*, signed_receipt: Path, identity_file: Path) -> None:\\n    _require_external_oidc()\\n    if not _port_free(8080) or not _port_free(18181):\\n        raise PreviewBlocked(\\\"HTTP_OR_SECOND_RUNTIME_PORT_OCCUPIED\\\")\\n    child_env = {k: v for k, v in os.environ.items()\\n                 if k not in {\\\"AOS_DATABASE_URL\\\", \\\"PGPASSWORD\\\", \\\"PGPASSFILE\\\"}}\\n    child = subprocess.run([sys.executable, str(Path(__file__).resolve()),\\n\", \".evidence/qyh-human-login-quality-review-20261013/scope-clarification.txt\": \"Bounded scope: management_app/serve_management_readonly are the local management-only path on18080. The original _require_external_oidc is the unchanged formal serve_limited path; it rejects localhost/http and is not claimed passed. Material app-integration.txt shows actual App providers nested inside LocalLoginGate. Original GET /v1/auth/oidc returns original public_config; entry config before app import fixes allow-dev=false and token URL. This review does not claim enterprise HTTPS, runtime Host admission, actual browser login or eight workbenches.\\n\", \".evidence/qyh-human-login-quality-review-20261013/public-policy-function-excerpt.txt\": \"\\n@router.get(\\\"/v1/auth/oidc\\\")\\ndef oidc_public_config() -> dict[str, Any]:\\n    return public_config()\\n\\n\", \".evidence/qyh-human-login-quality-review-20261013/current-original-envelope-material-2.txt\": \"import { getApiBase } from \\\"./apiBase\\\";\\nimport { applyMeToTenant, clearAccessToken, getTenant, setAccessToken, type MeResponse } from \\\"./tenant\\\";\\n\\n/** Original server authentication; credentials and refresh tokens never persist. */\\nexport async function loginPassword(username: string, password: string): Promise<void> {\\n  clearAccessToken();\\n  try {\\n    const response = await fetch(`${getApiBase()}/v1/auth/token`, {\\n      method: \\\"POST\\\", cache: \\\"no-store\\\",\\n      headers: { \\\"Content-Type\\\": \\\"application/json\\\" },\\n      body: JSON.stringify({ grantType: \\\"password\\\", username, password }),\\n    });\\n    if (!response.ok) throw new Error();\\n    const tokens = await response.json();\\n    if (typeof tokens.accessToken !== \\\"string\\\" || !tokens.accessToken.trim()) throw new Error();\\n    const tenant = getTenant();\\n    const meResponse = await fetch(`${getApiBase()}/v1/me`, {\\n      cache: \\\"no-store\\\",\\n      headers: { Authorization: `Bearer ${tokens.accessToken}`, \\\"X-Org-Id\\\": tenant.orgId, \\\"X-Project-Id\\\": tenant.projectId },\\n    });\\n    if (!meResponse.ok) throw new Error();\\n    const me: MeResponse = await meResponse.json();\\n    if (!me.subject || !me.orgId || !me.projectId) throw new Error();\\n    applyMeToTenant(me);\\n    setAccessToken(tokens.accessToken);\\n  } catch {\\n    clearAccessToken();\\n    throw new Error(\\\"登录失败，请核对账号、密码及工作区访问权限后重试。\\\");\\n  }\\n}\\n\", \".evidence/qyh-human-login-quality-review-20261013/current-original-envelope-material-3.txt\": \"import { afterEach, describe, expect, it, vi } from \\\"vitest\\\";\\nimport { loginPassword } from \\\"./passwordLogin\\\";\\nimport { clearAccessToken, getAccessToken, getTenant } from \\\"./tenant\\\";\\nimport { act, createElement } from \\\"react\\\";\\nimport { createRoot } from \\\"react-dom/client\\\";\\nimport { LocalLoginGate } from \\\"../components/auth/LocalLoginGate\\\";\\n\\nafterEach(() => { vi.unstubAllGlobals(); clearAccessToken(); });\\ndescribe(\\\"human password login\\\", () => {\\n  it(\\\"uses original grant and canonical me before publishing memory session\\\", async () => {\\n    const fetch = vi.fn().mockResolvedValueOnce(new Response(JSON.stringify({ accessToken: \\\"signed\\\", refreshToken: \\\"discard\\\" })))\\n      .mockResolvedValueOnce(new Response(JSON.string