\\", \\\"127.0.0.1\\\", \\\"::1\\\"}\\n                or parsed.username or parsed.password):\\n            raise PreviewBlocked(\\\"EXTERNAL_OIDC_CONFIG_INVALID\\\")\\n\\n\\ndef serve_limited(*, signed_receipt: Path, identity_file: Path) -> None:\\n    _require_external_oidc()\\n    if not _port_free(8080) or not _port_free(18181):\\n        raise PreviewBlocked(\\\"HTTP_OR_SECOND_RUNTIME_PORT_OCCUPIED\\\")\\n    child_env = {k: v for k, v in os.environ.items()\\n                 if k not in {\\\"AOS_DATABASE_URL\\\", \\\"PGPASSWORD\\\", \\\"PGPASSFILE\\\"}}\\n    child = subprocess.run([sys.executable, str(Path(__file__).resolve()),\\n\", \".evidence/qyh-human-login-quality-review-20261013/scope-clarification.txt\": \"Bounded scope: management_app/serve_management_readonly are the local management-only path on18080. The original _require_external_oidc is the unchanged formal serve_limited path; it rejects localhost/http and is not claimed passed. Material app-integration.txt shows actual App providers nested inside LocalLoginGate. Original GET /v1/auth/oidc returns original public_config; entry config before app import fixes allow-dev=false and token URL. This review does not claim enterprise HTTPS, runtime Host admission, actual browser login or eight workbenches.\\n\", \".evidence/qyh-human-login-quality-review-20261013/public-policy-function-excerpt.txt\": \"\\n@router.get(\\\"/v1/auth/oidc\\\")\\ndef oidc_public_config() -> dict[str, Any]:\\n    return public_config()\\n\\n\", \".evidence/qyh-human-login-quality-review-20261013/current-original-envelope-material-2.txt\": \"import { getApiBase } from \\\"./apiBase\\\";\\nimport { applyMeToTenant, clearAccessToken, getTenant, setAccessToken, type MeResponse } from \\\"./tenant\\\";\\n\\n/** Original server authentication; credentials and refresh tokens never persist. */\\nexport async function loginPassword(username: string, password: string): Promise<void> {\\n  clearAccessToken();\\n  try {\\n    const response = await fetch(`${getApiBase()}/v1/auth/token`, {\\n      method: \\\"POST\\\", cache: \\\"no-store\\\",\\n      headers: { \\\"Content-Type\\\": \\\"application/json\\\" },\\n      body: JSON.stringify({ grantType: \\\"password\\\", username, password }),\\n    });\\n    if (!response.ok) throw new Error();\\n    const tokens = await response.json();\\n    if (typeof tokens.accessToken !== \\\"string\\\" || !tokens.accessToken.trim()) throw new Error();\\n    const tenant = getTenant();\\n    const meResponse = await fetch(`${getApiBase()}/v1/me`, {\\n      cache: \\\"no-store\\\",\\n      headers: { Authorization: `Bearer ${tokens.accessToken}`, \\\"X-Org-Id\\\": tenant.orgId, \\\"X-Project-Id\\\": tenant.projectId },\\n    });\\n    if (!meResponse.ok) throw new Error();\\n    const me: MeResponse = await meResponse.json();\\n    if (!me.subject || !me.orgId || !me.projectId) throw new Error();\\n    applyMeToTenant(me);\\n    setAccessToken(tokens.accessToken);\\n  } catch {\\n    clearAccessToken();\\n    throw new Error(\\\"登录失败，请核对账号、密码及工作区访问权限后重试。\\\");\\n  }\\n}\\n\", \".evidence/qyh-human-login-quality-review-20261013/current-original-envelope-material-3.txt\": \"import { afterEach, describe, expect, it, vi } from \\\"vitest\\\";\\nimport { loginPassword } from \\\"./passwordLogin\\\";\\nimport { clearAccessToken, getAccessToken, getTenant } from \\\"./tenant\\\";\\nimport { act, createElement } from \\\"react\\\";\\nimport { createRoot } from \\\"react-dom/client\\\";\\nimport { LocalLoginGate } from \\\"../components/auth/LocalLoginGate\\\";\\n\\nafterEach(() => { vi.unstubAllGlobals(); clearAccessToken(); });\\ndescribe(\\\"human password login\\\", () => {\\n  it(\\\"uses original grant and canonical me before publishing memory session\\\", async () => {\\n    const fetch = vi.fn().mockResolvedValueOnce(new Response(JSON.stringify({ accessToken: \\\"signed\\\", refreshToken: \\\"discard\\\" })))\\n      .mockResolvedValueOnce(new Response(JSON.stringify({ subject: \\\"human\\\", orgId: \\\"org-org\\\", projectId: \\\"dev-project\\\", workspaceName: \\\"真实工作区\\\", roles: [\\\"admin\\\"], markings: [], tokenKind: \\\"oidc\\\" })));\\n    vi.stubGlobal(\\\"fetch\\\", fetch);\\n    await loginPassword(\\\"user\\\", \\\"private\\\");\\n    expect(fetch.mock.calls[0][0]).toContain(\\\"/v1/auth/token\\\");\\n    expect(JSON.parse(fetch.mock.calls[0][1].body)).toEqual({ grantType: \\\"password\\\", username: \\\"user\\\", password: \\\"private\\\" });\\n    expect(fetch.mock.calls[1][1].headers.Authorization).toBe(\\\"Bearer signed\\\");\\n    expect(getAccessToken()).toBe(\\\"signed\\\");\\n    expect(getTenant().subject).toBe(\\\"human\\\");\\n    expect(localStorage.getItem(\\\"access_token\\\")).toBeNull();\\n    expect(sessionStorage.getItem(\\\"refresh_token\\\")).toBeNull();\\n  });\\n  it(\\\"does not retry rejected credentials or publish a session\\\", async () => {\\n    const fetch = vi.fn().mockResolvedValue(new Response(\\\"private provider detail\\\", { status: 401 }));\\n    vi.stubGlobal(\\\"fetch\\\", fetch);\\n    await expect(loginPassword(\\\"user\\\", \\\"private\\\")).rejects.toThrow(\\\"登录失败\\\");\\n    expect(fetch).toHaveBeenCalledTimes(1);\\n    expect(getAccessToken()).toBeNull();\\n  });\\n  it(\\\"rejects incomplete token responses before fetching identity\\\", async () => {\\n    const fetch = vi.fn().mockResolvedValue(new Response(\\\"{}\\\")); vi.stubGlobal(\\\"fetch\\\", fetch);\\n    await expect(loginPassword(\\\"user\\\", \\\"private\\\")).rejects.toThrow(\\\"登录失败\\\");\\n    expect(fetch).toHaveBeenCalledTimes(1); expect(getAccessToken()).toBeNull();\\n  });\\n  it(\\\"does not expose an unverified session when canonical me fails\\\", async () => {\\n    const fetch = vi.fn().mockResolvedValueOnce(new Response('{\\\"accessToken\\\":\\\"signed\\\"}'))\\n      .mockResolvedValueOnce(new Response(\\\"{}\\\", { status: 403 })); vi.stubGlobal(\\\"fetch\\\", fetch);\\n    await expect(loginPassword(\\\"user\\\", \\\"private\\\")).rejects.toThrow(\\\"登录失败\\\");\\n    expect(getAccessToken()).toBeNull();\\n  });\\n});\\n\\ndescribe(\\\"server login policy gate\\\", () => {\\n  async function renderPolicy(body: unknown, status = 200) {\\n    vi.stubGlobal(\\\"IS_REACT_ACT_ENVIRONMENT\\\", true);\\n    vi.stubGlobal(\\\"fetch\\\", vi.fn().mockResolvedValue(new Response(JSON.stringify(body), { status })));\\n    const container = document.createElement(\\\"div\\\");\\n    const root = createRoot(container);\\n    await act(async () => { root.render(createElement(LocalLoginGate, { children: \\\"business catalog\\\" })); });\\n    const text = container.textContent;\\n    await act(async () => root.unmount());\\n    return text;\\n  }\\n  it(\\\"preserves the explicitly enabled legacy development UI\\\", async () => {\\n    expect(await renderPolicy({ allowDevToken: true })).toContain(\\\"business catalog\\\");\\n  });\\n  it(\\\"requires human login before mounting business consumers\\\", async () => {\\n    const text = await renderPolicy({ allowDevToken: false, tokenUrlConfigured: true, grantTypes: [\\\"password\\\"] });\\n    expect(text).toContain(\\\"登录名\\\"); expect(text).not.toContain(\\\"business catalog\\\");\\n  });\\n  it(\\\"fails closed for unreadable or unsupported login configuration\\\", async () => {\\n    for (const [body, status] of [[{}, 200], [{ allowDevToken: false }, 200], [{}, 503]] as const) {\\n      const text = await renderPolicy(body, status);\\n      expect(text).toContain(\\\"登录服务暂不可用\\\"); expect(text).not.toContain(\\\"business catalog\\\");\\n    }\\n  });\\n});\\n\", \".evidence/qyh-human-login-quality-review-20261013/original-server-response-excerpt.txt\": \"        log.warning(\\\"oidc_password_grant_fail err=%s\\\", type(exc).__name__)\\n        raise ValueError(f\\\"IdP token failed: {exc}\\\") from exc\\n    access = raw.get(\\\"access_token\\\")\\n    if not access:\\n        raise ValueError(\\\"IdP response missing access_token\\\")\\n    return {\\n        \\\"accessToken\\\": access,\\n        \\\"tokenType\\\": raw.get(\\\"token_type\\\") or \\\"Bearer\\\",\\n        \\\"expiresIn\\\": int(raw.get(\\\"expires_in\\\") or 3600),\\n        \\\"issuer\\\": issuer(),\\n        \\\"tokenKind\\\": \\\"oidc-keycloak\\\",\\n        \\\"alg\\\": \\\"RS256\\\",\\n        \\\"refreshToken\\\": raw.get(\\\"refresh_token\\\"),\\n    }\\n\\n\\ndef issue_dev_token(\\n    *,\\n\", \".evidence/qyh-human-login-quality-review-20261013/actual-envelope-correction.txt\": \"Live original API POST returned200; first acceptance script and Web mocked IdP snake_case instead of original AOS camelCase. Corrected current source uses original accessToken exactly; real contract fixture RED1/6PASS then13/13GREEN and corrected production build passed. Preserved initial verifier failure, read-only reconciled its exact single session and closed only known selftest. Second original API credential request and me returned200 with canonical UUID/scope/admin; profile displayName did not match because managed boot loads membership catalog but not legacy person cache. Native logout204 closed that second session. Browser login/legacy profile hydration and eight runtime pages remain pending. No full acceptance claimed.\\n\"}}"}],"timestamp":1791829540824},{"role":"assistant","content":[{"type":"text","text":"{\n  \"request_id\": \"qyh-human-login-quality-review-20261013-r5\",\n  \"task_id\": \"qyh-human-login-quality-review-20261013\",\n  \"owner\": \"codex-01a107a2-e9e4-7670-bc44-1144fa9b27e2\",\n  \"kind\": \"quality\",\n  \"baseline\": {\n    \"head\": \"d589cad90833c0f0165f3be6b4fd8f7a809a7dfb\",\n    \"authority_revision\": \"AOS-001987\",\n    \"files\": {\n      \".evidence/qyh-human-login-quality-review-20261013/public-code-material-0.txt\": \"79977f32ef3645767ad4d674ac8acbf052a28e28a23926da351a8878f4ed312e\",\n      \".evidence/qyh-human-login-quality-review-20261013/public-code-material-1.txt\": \"ba142f98